// Do not edit this file.

package coinchange

import "testing"

func check(t *testing.T, coins []int, amount, want int) {
	t.Helper()
	if got := CoinChange(coins, amount); got != want {
		t.Fatalf("CoinChange(%v, %d) = %d, want %d", coins, amount, got, want)
	}
}

func TestClassic(t *testing.T)         { check(t, []int{1, 2, 5}, 11, 3) }
func TestImpossible(t *testing.T)      { check(t, []int{2}, 3, -1) }
func TestZeroAmount(t *testing.T)      { check(t, []int{1}, 0, 0) }
func TestSingleCoinExact(t *testing.T) { check(t, []int{7}, 21, 3) }

// greedy takes 4+1+1 (3 coins); optimal is 3+3 (2 coins)
func TestGreedyFails(t *testing.T)       { check(t, []int{1, 3, 4}, 6, 2) }
func TestUnsortedCoins(t *testing.T)     { check(t, []int{5, 1, 2}, 7, 2) }
func TestNoOnesReachable(t *testing.T)   { check(t, []int{3, 7}, 13, 3) }
func TestNoOnesUnreachable(t *testing.T) { check(t, []int{3, 7}, 11, -1) }
func TestLargerAmount(t *testing.T)      { check(t, []int{186, 419, 83, 408}, 6249, 20) }
